class Solution {
public:
    int captureForts(std::vector<int>& forts) {
        int ans = 0;
        int last_idx = -1;
        for (int i = 0; i < (int)forts.size(); ++i) {
            if (forts[i] != 0) {
                if (last_idx != -1 && forts[last_idx] == -forts[i]) {
                    ans = std::max(ans, i - last_idx - 1);
                }
                last_idx = i;
            }
        }
        return ans;
    }
};

class Solution {
    public int captureForts(int[] forts) {
        int ans = 0;
        int lastIdx = -1;
        for (int i = 0; i < forts.length; i++) {
            if (forts[i] != 0) {
                if (lastIdx != -1 && forts[lastIdx] == -forts[i]) {
                    ans = Math.max(ans, i - lastIdx - 1);
                }
                lastIdx = i;
            }
        }
        return ans;
    }
}

var captureForts = function(forts) {
    let ans = 0;
    let lastIdx = -1;
    for (let i = 0; i < forts.length; i++) {
        if (forts[i] !== 0) {
            if (lastIdx !== -1 && forts[lastIdx] === -forts[i]) {
                const diff = i - lastIdx - 1;
                if (diff > ans) ans = diff;
            }
            lastIdx = i;
        }
    }
    return ans;
};
